INSERT INTO "Permission" ("id","code","name","createdAt") VALUES (gen_random_uuid(),'leaves.configure','إعداد رصيد إجازات الشركة',CURRENT_TIMESTAMP),(gen_random_uuid(),'leaves.manage_balances','تعديل استحقاق إجازات المندوب',CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "RolePermission" ("id","roleId","permissionId","createdAt") SELECT gen_random_uuid(),r."id",p."id",CURRENT_TIMESTAMP FROM "Role" r CROSS JOIN "Permission" p WHERE r."isSystem"=true AND ((r."code" IN ('NATIONAL_MANAGER','SUPER_ADMIN') AND p."code" IN ('leaves.configure','leaves.manage_balances')) OR (r."code"='TEAM_MANAGER' AND p."code"='leaves.manage_balances')) ON CONFLICT ("roleId","permissionId") DO NOTHING;
